/**
 * Rare-disease trial desert map (2026).
 *
 * Core question: Which WHO regions host almost no interventional rare-disease
 * trials despite material estimated patient counts?
 *
 * Perimeter: interventional studies on ClinicalTrials.gov tagged to rare /
 * orphan conditions (condition + orphan-drug keyword filters; recruiting /
 * active / completed, not observational-only), mapped to WHO regions via
 * facility country. Patient-burden anchors use Orphanet prevalence literature
 * and WHO regional population denominators ??? not a registry census of every
 * rare diagnosis, so "patients" are modeled estimates.
 *
 * Headline meter: interventional rare-disease trials per million population.
 */

export type Confidence = "disclosed" | "estimated" | "modeled";

export const VIZ_MARKER = "Rare-disease trial deserts ??? trials per million";

export const SOURCE_NOTE =
