export const SOURCES = [
  {
    label: "ClinicalTrials.gov ??? interventional rare/orphan studies",
    url: "https://clinicaltrials.gov/",
  },
  {
    label: "Orphanet Report Series ??? Prevalence of rare diseases",
    url: "https://www.orpha.net/consor/cgi-bin/Education_AboutRareDiseases.php?lng=EN",
  },
