  { region: "SEAR", oncologyHeme: 44, metabolic: 11, neuro: 10, immuno: 12, other: 23 },
  { region: "EMR", oncologyHeme: 41, metabolic: 14, neuro: 11, immuno: 13, other: 21 },
  { region: "WPR", oncologyHeme: 46, metabolic: 13, neuro: 12, immuno: 11, other: 18 },
  { region: "AMR", oncologyHeme: 42, metabolic: 15, neuro: 16, immuno: 12, other: 15 },
  { region: "EUR", oncologyHeme: 39, metabolic: 17, neuro: 18, immuno: 13, other: 13 },
];

/** Year path: rare interventional starts by WHO region (index 2018=100 for EUR) */
export type YearPathRow = {
  year: number;
  AFR: number;
  AMR: number;
  EMR: number;
  EUR: number;
  SEAR: number;
  WPR: number;
};

export const YEAR_PATH: YearPathRow[] = [
  { year: 2018, AFR: 42, AMR: 980, EMR: 78, EUR: 1120, SEAR: 160, WPR: 240 },
  { year: 2019, AFR: 48, AMR: 1040, EMR: 88, EUR: 1180, SEAR: 185, WPR: 270 },
  { year: 2020, AFR: 39, AMR: 910, EMR: 72, EUR: 990, SEAR: 150, WPR: 230 },
  { year: 2021, AFR: 51, AMR: 1080, EMR: 95, EUR: 1210, SEAR: 210, WPR: 310 },
  { year: 2022, AFR: 58, AMR: 1160, EMR: 110, EUR: 1280, SEAR: 245, WPR: 360 },
  { year: 2023, AFR: 64, AMR: 1220, EMR: 125, EUR: 1340, SEAR: 280, WPR: 410 },
  { year: 2024, AFR: 72, AMR: 1290, EMR: 138, EUR: 1390, SEAR: 320, WPR: 460 },
  { year: 2025, AFR: 78, AMR: 1340, EMR: 148, EUR: 1420, SEAR: 350, WPR: 510 },
];

export type MetricKey = "trialsPerMillion" | "trialsPer100kPatients" | "desertIndex";

export const METRIC_OPTIONS: { key: MetricKey; label: string }[] = [
  { key: "trialsPerMillion", label: "Trials per million pop." },
  { key: "trialsPer100kPatients", label: "Trials per 100k rare patients" },
  { key: "desertIndex", label: "Desert index (patients??trials)" },
];

export const REGION_FILTERS = [
  { id: "all", label: "All WHO regions" },
  { id: "AFR", label: "African Region" },
  { id: "SEAR", label: "South-East Asia" },
  { id: "EMR", label: "Eastern Mediterranean" },
  { id: "WPR", label: "Western Pacific" },
  { id: "AMR", label: "Americas" },
  { id: "EUR", label: "European Region" },
] as const;

export type RegionFilterId = (typeof REGION_FILTERS)[number]["id"];

export function fmtNum(n: number, digits = 1): string {
  return n.toLocaleString("en-US", {
    maximumFractionDigits: digits,
    minimumFractionDigits: Number.isInteger(n) ? 0 : Math.min(digits, 1),
  });
}

export function rankedRegionsBy(metric: MetricKey): RegionDesertRow[] {
  return [...REGION_DESERTS].sort((a, b) => b[metric] - a[metric]);
}

export const ANALYTICS = {
  desertRegions: REGION_DESERTS.filter((r) => r.desertIndex >= 1.4).map((r) => r.region),
  topDesert: REGION_DESERTS.reduce((a, b) => (a.desertIndex > b.desertIndex ? a : b)),
  densest: REGION_DESERTS.reduce((a, b) =>
    a.trialsPerMillion > b.trialsPerMillion ? a : b,
  ),
  eurAfrGap: HEADLINE.eurAfrGapRatio,
};

