      rows = rows.filter((r) => /3GC|cefotaxime|methicillin/i.test(r.drug));
    }
    return rows.map((r) => ({
      name: `${r.pathogen.split(" ")[0]} ?? ${REGION_SHORT[r.geography as keyof typeof REGION_SHORT] ?? r.geography.replace(/ Region$/, "").slice(0, 12)}`,
