args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ANALYTICS,
  COUNTRY_EXEMPLARS,
  HEADLINE,
  METRIC_OPTIONS,
  REGION_DESERTS,
  REGION_FILTERS,
  SOURCE_NOTE,
  THERAPY_MIX,
  VIZ_MARKER,
  YEAR_PATH,
  fmtNum,
  rankedRegionsBy,
  type MetricKey,
  type RegionFilterId,
  type WhoRegionCode,
} from "@/data/rare-disease-trial-desert-map-2026-data";

// viz-types: desert bars, patient??trial scatter, year area path, therapy stacked bars, exemplar ladder | controls: metric + region filter + view

type ViewId = "deserts" | "scatter" | "path" | "therapy" | "countries";

const REGION_COLORS: Record<WhoRegionCode, string> = {
  AFR: "#f97316",
  SEAR: "#eab308",
  EMR: "#a855f7",
  WPR: "#22c55e",
  AMR: "#0ea5e9",
  EUR: "#38bdf8",
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

export function RareDiseaseTrialDesertMap2026Dashboard() {
  const [view, setView] = useState<ViewId>("deserts");
  const [metric, setMetric] = useState<MetricKey>("trialsPerMillion");
  const [regionFilter, setRegionFilter] = useState<RegionFilterId>("all");

  const metricLabel =
    METRIC_OPTIONS.find((m) => m.key === metric)?.label ?? metric;

  const desertBars = useMemo(() => {
    let rows = rankedRegionsBy(metric);
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows.map((r) => ({
      name: r.region,
      label: r.label,
      value: r[metric],
      fill: REGION_COLORS[r.region],
      desertIndex: r.desertIndex,
    }));
  }, [metric, regionFilter]);

  const scatterData = useMemo(() => {
    let rows = REGION_DESERTS;
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows.map((r) => ({
      name: r.region,
      label: r.label,
      patientShare: r.patientSharePct,
      trialShare: r.trialSharePct,
      desertIndex: r.desertIndex,
      z: Math.max(40, r.popM / 8),
      fill: REGION_COLORS[r.region],
    }));
  }, [regionFilter]);

  const pathData = useMemo(() => YEAR_PATH, []);

  const therapyRows = useMemo(() => {
    let rows = THERAPY_MIX;
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows.map((r) => ({
      name: r.region,
      Oncology: r.oncologyHeme,
      Metabolic: r.metabolic,
      Neuro: r.neuro,
      Immuno: r.immuno,
      Other: r.other,
    }));
  }, [regionFilter]);

  const exemplars = useMemo(() => {
    let rows = [...COUNTRY_EXEMPLARS];
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows
      .sort((a, b) => a.trialsPerMillion - b.trialsPerMillion)
      .map((r) => ({
        name: r.country.length > 14 ? `${r.country.slice(0, 12)}???` : r.country,
        full: r.country,
        trialsPerMillion: r.trialsPerMillion,
        trials: r.trials,
        fill: REGION_COLORS[r.region],
        region: r.region,
      }));
  }, [regionFilter]);

  const parityLine = useMemo(
    () => [
      { patientShare: 0, trialShare: 0 },
      { patientShare: 25, trialShare: 25 },
    ],
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="rare-disease-trial-desert-map-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-orange-950 px-5 py-5 text-white sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-widest text-orange-300/90">
          {VIZ_MARKER}
        </p>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-200 sm:text-base">
          Europe runs about{" "}
          <span className="font-semibold text-white">
            {fmtNum(HEADLINE.eurTrialsPerMillion)}
          </span>{" "}
          interventional rare-disease trials per million people; the African
          Region sits near{" "}
          <span className="font-semibold text-white">
            {fmtNum(HEADLINE.afrTrialsPerMillion)}
          </span>{" "}
          ??? a roughly{" "}
          <span className="font-semibold text-white">
            {fmtNum(HEADLINE.eurAfrGapRatio, 0)}??
          </span>{" "}
          gap. AFR holds ~{fmtNum(HEADLINE.afrPatientSharePct)}% of modeled rare
          patients on ~{fmtNum(HEADLINE.afrTrialSharePct)}% of trials. Toggle
          meters, filter WHO regions, and flip desert / scatter / path / therapy
          / country views.
        </p>
      </div>

      <div className="flex flex-col gap-3 lg:flex-row lg:flex-wrap lg:items-end lg:justify-between">
        <div className="flex flex-wrap gap-2">
          {(
            [
              ["deserts", "Desert ladder"],
              ["scatter", "Patient ?? trial"],
              ["path", "Start path"],
              ["therapy", "Therapy mix"],
              ["countries", "Country exemplars"],
            ] as [ViewId, string][]
          ).map(([id, label]) => (
            <button
              key={id}
              type="button"
              onClick={() => setView(id)}
              className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                view === id
                  ? "bg-slate-900 text-white"
                  : "border border-slate-200 bg-white text-slate-600 hover:bg-slate-50"
              }`}
            >
              {label}
            </button>
          ))}
        </div>

        <div className="flex flex-wrap gap-3">
          <label className="flex flex-col gap-1 text-xs font-semibold uppercase tracking-wide text-slate-500">
            Meter
            <select
              className="min-w-[12rem] rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-medium normal-case text-slate-800"
              value={metric}
              onChange={(e) => setMetric(e.target.value as MetricKey)}
            >
              {METRIC_OPTIONS.map((m) => (
                <option key={m.key} value={m.key}>
                  {m.label}
                </option>
              ))}
            </select>
          </label>
          <label className="flex flex-col gap-1 text-xs font-semibold uppercase tracking-wide text-slate-500">
            WHO region
            <select
              className="min-w-[12rem] rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-medium normal-case text-slate-800"
              value={regionFilter}
              onChange={(e) =>
                setRegionFilter(e.target.value as RegionFilterId)
              }
            >
              {REGION_FILTERS.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.label}
                </option>
              ))}
            </select>
          </label>
        </div>
      </div>

      {view === "deserts" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title={`${metricLabel} by WHO region`}
            subtitle={`Top desert: ${ANALYTICS.topDesert.label} (index ${fmtNum(ANALYTICS.topDesert.desertIndex)})`}
          >
            <div className="h-[320px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={desertBars}
                  layout="vertical"
                  margin={{ left: 8, right: 16, top: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={48}
                    tick={{ fontSize: 12 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmtNum(Number(v)), metricLabel]}
                    labelFormatter={(_, payload) =>
                      String(payload?.[0]?.payload?.label ?? "")
                    }
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {desertBars.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Trial share vs patient share"
            subtitle="Points above the parity line are trial-rich; below are deserts"
          >
            <div className="h-[320px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={scatterData}
                  margin={{ left: 8, right: 16, top: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="patientShare"
                    name="Patient share %"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Patient share %",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="trialShare"
                    name="Trial share %"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Trial share %",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      fmtNum(Number(v)),
                      String(name),
                    ]}
                    labelFormatter={(_, p) =>
                      String(p?.[0]?.payload?.label ?? "")
                    }
                  />
                  <Line
                    data={parityLine}
                    type="linear"
                    dataKey="trialShare"
                    stroke="#94a3b8"
                    strokeDasharray="4 4"
                    dot={false}
                    legendType="none"
                    isAnimationActive={false}
                  />
                  <Scatter data={scatterData} fill="#f97316">
                    {scatterData.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Scatter>
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Desert scatter ??? patient burden vs trial presence"
          subtitle="Bubble size scales with regional population; desert index in tooltip"
        >
          <div className="h-[380px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ left: 8, right: 16, top: 8, bottom: 24 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="patientShare"
                  name="Patient %"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Share of modeled rare patients (%)",
                    position: "insideBottom",
                    offset: -8,
                    fontSize: 12,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="trialShare"
                  name="Trial %"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Share of rare trials (%)",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 12,
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[80, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) => [fmtNum(Number(v)), String(name)]}
                  labelFormatter={(_, p) =>
                    String(p?.[0]?.payload?.label ?? "")
                  }
                />
                <Scatter data={scatterData}>
                  {scatterData.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "path" && (
        <ChartCard
          title="Interventional rare-disease trial starts by WHO region"
          subtitle="Annual starts (facility-mapped). COVID dip in 2020, then uneven recovery."
        >
          <div className="h-[380px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart
                data={pathData}
                margin={{ left: 8, right: 16, top: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Legend />
                <Area
                  type="monotone"
                  dataKey="EUR"
                  stackId="1"
                  stroke={REGION_COLORS.EUR}
                  fill={REGION_COLORS.EUR}
                  fillOpacity={0.55}
                />
                <Area
                  type="monotone"
                  dataKey="AMR"
                  stackId="1"
                  stroke={REGION_COLORS.AMR}
                  fill={REGION_COLORS.AMR}
                  fillOpacity={0.55}
                />
                <Area
                  type="monotone"
                  dataKey="WPR"
                  stackId="1"
                  stroke={REGION_COLORS.WPR}
                  fill={REGION_COLORS.WPR}
                  fillOpacity={0.55}
                />
                <Area
                  type="monotone"
                  dataKey="SEAR"
                  stackId="1"
                  stroke={REGION_COLORS.SEAR}
                  fill={REGION_COLORS.SEAR}
                  fillOpacity={0.55}
                />
                <Area
                  type="monotone"
                  dataKey="EMR"
                  stackId="1"
                  stroke={REGION_COLORS.EMR}
                  fill={REGION_COLORS.EMR}
                  fillOpacity={0.55}
                />
                <Area
                  type="monotone"
                  dataKey="AFR"
                  stackId="1"
                  stroke={REGION_COLORS.AFR}
                  fill={REGION_COLORS.AFR}
                  fillOpacity={0.75}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "therapy" && (
        <ChartCard
          title="Rare interventional therapy mix by WHO region"
          subtitle="Row percentages ??? oncology/heme still dominates thin desert pipelines"
        >
          <div className="h-[360px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={therapyRows}
                margin={{ left: 8, right: 16, top: 8, bottom: 8 }}
              >
