// viz-types: desert bars, patient??trial scatter, year area path, therapy stacked bars, exemplar ladder | controls: metric + region filter + view

type ViewId = "deserts" | "scatter" | "path" | "therapy" | "countries";

const REGION_COLORS: Record<WhoRegionCode, string> = {
  AFR: "#f97316",
  SEAR: "#eab308",
  EMR: "#a855f7",
  WPR: "#22c55e",
  AMR: "#0ea5e9",
  EUR: "#38bdf8",
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

export function RareDiseaseTrialDesertMap2026Dashboard() {
  const [view, setView] = useState<ViewId>("deserts");
  const [metric, setMetric] = useState<MetricKey>("trialsPerMillion");
  const [regionFilter, setRegionFilter] = useState<RegionFilterId>("all");

  const metricLabel =
    METRIC_OPTIONS.find((m) => m.key === metric)?.label ?? metric;

  const desertBars = useMemo(() => {
    let rows = rankedRegionsBy(metric);
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows.map((r) => ({
      name: r.region,
      label: r.label,
      value: r[metric],
      fill: REGION_COLORS[r.region],
      desertIndex: r.desertIndex,
    }));
  }, [metric, regionFilter]);

  const scatterData = useMemo(() => {
    let rows = REGION_DESERTS;
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows.map((r) => ({
      name: r.region,
      label: r.label,
      patientShare: r.patientSharePct,
      trialShare: r.trialSharePct,
      desertIndex: r.desertIndex,
      z: Math.max(40, r.popM / 8),
      fill: REGION_COLORS[r.region],
    }));
  }, [regionFilter]);

  const pathData = useMemo(() => YEAR_PATH, []);

  const therapyRows = useMemo(() => {
    let rows = THERAPY_MIX;
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows.map((r) => ({
      name: r.region,
      Oncology: r.oncologyHeme,
      Metabolic: r.metabolic,
      Neuro: r.neuro,
      Immuno: r.immuno,
      Other: r.other,
    }));
