  const exemplars = useMemo(() => {
    let rows = [...COUNTRY_EXEMPLARS];
    if (regionFilter !== "all") {
      rows = rows.filter((r) => r.region === regionFilter);
    }
    return rows
      .sort((a, b) => a.trialsPerMillion - b.trialsPerMillion)
      .map((r) => ({
        name: r.country.length > 14 ? `${r.country.slice(0, 12)}???` : r.country,
        full: r.country,
        trialsPerMillion: r.trialsPerMillion,
        trials: r.trials,
        fill: REGION_COLORS[r.region],
        region: r.region,
      }));
  }, [regionFilter]);

  const parityLine = useMemo(
    () => [
      { patientShare: 0, trialShare: 0 },
      { patientShare: 25, trialShare: 25 },
    ],
    [],
