      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-orange-950 px-5 py-5 text-white sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-widest text-orange-300/90">
