/**
 * QA: rare-disease-trial-desert-map-2026
 * // viz-types: desert bars, patient??trial scatter, year area path, therapy stacked bars, exemplar ladder | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  ANALYTICS,
  COUNTRY_EXEMPLARS,
  HEADLINE,
  REGION_DESERTS,
  THERAPY_MIX,
  YEAR_PATH,
} from "../src/data/rare-disease-trial-desert-map-2026-data.ts";

assert.equal(HEADLINE.eurTrialsPerMillion, 11.4);
assert.equal(HEADLINE.afrTrialsPerMillion, 0.38);
assert.equal(HEADLINE.eurAfrGapRatio, 30.0);
assert.equal(HEADLINE.afrTrialSharePct, 2.1);
assert.equal(HEADLINE.afrPatientSharePct, 14.8);
assert.ok(REGION_DESERTS.length >= 6);
assert.ok(COUNTRY_EXEMPLARS.length >= 8);
assert.ok(THERAPY_MIX.length >= 6);
assert.ok(YEAR_PATH.length >= 6);
assert.equal(ANALYTICS.topDesert.region, "AFR");
assert.ok(ANALYTICS.eurAfrGap >= 25);

const root = process.cwd();
const slug = "rare-disease-trial-desert-map-2026";
const markers = [
  "Rare-disease trial deserts ??? trials per million",
  "Clinical development",
];

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4186);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }

    const selects = page.locator("select");
    assert.ok((await selects.count()) >= 2, "expected >=2 select controls");
    await selects.nth(0).selectOption({ value: "desertIndex" });
    await page.waitForTimeout(250);
    await selects.nth(1).selectOption({ value: "AFR" });
    await page.waitForTimeout(250);
    console.log("??? meter + region controls");

    const audit = await auditVizInteractions(page);
    if (audit.issues?.length) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    if (audit.warnings?.length) {
      console.log("warnings:", audit.warnings.join(" | "));
    }
    console.log(`qa-${slug}: PASS`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

